def trigger_row(table, name, kind, deferred, function, arguments=(), parent=None):
    """Pin trigger arguments and parent names without copying database OIDs."""
    encoded = ''.join(argument + '\0' for argument in arguments).encode().hex()
    return [table, name, 'O', kind, deferred, deferred, 'public', function,
            encoded, len(arguments), [], True, False, parent]


def check(value, refused):
    """Require reviewed77 metadata and the exact78/79 replacement bodies on both catalogs."""
    functions = {row[0]: row for row in value.get('functions', [])}
    for name, metadata in FUNCTIONS.items():
        row = functions.get(name)
        if row is None or len(row) != 11 or row[1:10] != metadata or not row[10]:
            raise refused('extensions77_function_metadata_invalid')
        if (not isinstance(row[10], str)
                or hashlib.sha256(row[10].encode()).hexdigest() != FUNCTION_BODY_SHA256[name]):
            raise refused('extensions77_function_body_invalid')
    if value.get('extensions77_function_defaults') != FUNCTION_DEFAULTS:
        raise refused('extensions77_function_defaults_invalid')
    columns = [row for row in value.get('columns', [])
               if row[0] in TABLES or row[:2] == ['runs', 'payload_mode']]
    if columns != COLUMNS:
        raise refused('extensions77_column_invalid')
    constraints = [row for row in value.get('constraints', [])
                   if row[0] in TABLES or row[:2] == ['runs', 'runs_payload_mode_check']]
    if constraints != CONSTRAINTS:
        raise refused('extensions77_constraint_invalid')
    if value.get('extensions77_indexes') != INDEXES:
        raise refused('extensions77_index_invalid')
    # The existing conversation checker validates this complete recursive
    # relation inventory first. Only actual attached child relations qualify.
    relations = value.get('conversation_event_relations')
    if not isinstance(relations, list) or not 2 <= len(relations) <= 1024:
        raise refused('extensions77_event_relations_invalid')
    expected = list(TRIGGERS)
    root = next((row for row in expected if row[:2] == ['events', 'employee_memory_epoch_events']), None)
    if root is None:
        raise refused('extensions77_catalog_not_final')
    for row in relations:
        if not isinstance(row, list) or len(row) != 7 or row[0] != 'public':
            raise refused('extensions77_event_relations_invalid')
        if row[1] != 'events':
            expected.append([row[1], *root[1:13], ['public', row[3], root[1]]])
    actual = value.get('extensions77_triggers')
    if (not isinstance(actual, list) or any(not isinstance(row, list) or len(row) != 14
            or not all(isinstance(key, str) and key for key in row[:2]) for row in actual)
            or sorted(actual, key=lambda row: row[:2]) != sorted(expected, key=lambda row: row[:2])):
        raise refused('extensions77_trigger_invalid')
    if not set(TABLES) <= {row[0] for row in value.get('fence_targets', [])}:
        raise refused('extensions77_community_fence_missing')


